mapper.select:
SELECT receiptDate, operatorName, channel, businessType, COUNT(*) AS count, SUM(amountFen) AS amountFen FROM ( SELECT DATE_FORMAT(CONVERT_TZ(p.paid_at, '+00:00', '+08:00'), '%Y-%m-%d') AS receiptDate, '用户自助' AS operatorName, p.provider AS channel, 'ONLINE_BOOKING' AS businessType, p.amount_fen AS amountFen FROM s_payment p JOIN s_booking b ON b.id = p.booking_id WHERE b.venue_id = #{venueId} AND p.status = 'SUCCESS' AND p.paid_at >= #{startAt} AND p.paid_at < #{endAt}
UNION ALL
SELECT DATE_FORMAT(CONVERT_TZ(rf.refunded_at, '+00:00', '+08:00'), '%Y-%m-%d') AS receiptDate, '系统退款' AS operatorName, p.provider AS channel, 'ONLINE_REFUND' AS businessType, -rf.amount_fen AS amountFen FROM s_refund rf JOIN s_payment p ON p.id = rf.payment_id JOIN s_booking b ON b.id = rf.booking_id WHERE b.venue_id = #{venueId} AND rf.status = 'SUCCESS' AND rf.refunded_at >= #{startAt} AND rf.refunded_at < #{endAt}
UNION ALL
SELECT DATE_FORMAT(CONVERT_TZ(r.succeeded_at, '+00:00', '+08:00'), '%Y-%m-%d') AS receiptDate, COALESCE(e.name, a.display_name, '用户自助') AS operatorName, r.channel, 'RECHARGE' AS businessType, r.paid_amount_fen AS amountFen FROM s_member_recharge r JOIN s_venue_customer vc ON vc.id = r.venue_customer_id LEFT JOIN s_admin_account a ON a.id = r.operator_admin_id LEFT JOIN s_employee e ON e.id = r.operator_employee_id WHERE vc.venue_id = #{venueId} AND r.status = 'SUCCESS' AND r.succeeded_at >= #{startAt} AND r.succeeded_at < #{endAt} ) receipt_events GROUP BY receiptDate, operatorName, channel, businessType ORDER BY receiptDate, operatorName, channel, businessType
